import {renderPresentation} from './presentation.js';
import {publishedData} from './published.js?v=visual4';
import './screen-fit.js';
import {data,cloud} from './store.js';
import {esc,safeImage,dates,pretty,money,yt} from './util.js';
import { expandScreenings, groupScreenings } from './screenings.js';
import {admin} from './panel.js?v=visual4';
const $=s=>document.querySelector(s),days=['Hoy','Mañana','Tercer día'];
let db={movies:[],candy:[],upcoming:[]},dateList=dates(),day=0,mi=0,ci=0,vi=0,paused=false,manual=0,mt=0,ct=0,vt=0,frame,ready=false,playing=false,pendingEnded=false;
const empty=s=>'<p class="empty">'+s+'</p>';
const img=(v,cls)=>'<img class="'+cls+'" alt="" src="'+(safeImage(v)||'assets/placeholder.svg')+'">';
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.src.endsWith('placeholder.svg'))e.target.src='assets/placeholder.svg'},true);
const controls=(k,i,n)=>'<div class="controls"><span class="count">'+String(i+1).padStart(2,'0')+' / '+String(n).padStart(2,'0')+'</span><div>'+[-1,1].map(d=>'<button data-k="'+k+'" data-d="'+d+'" aria-label="'+(d<0?'Anterior':'Siguiente')+' · '+k+'">'+(d<0?'‹':'›')+'</button>').join('')+'</div></div>';
const films=()=>groupScreenings(db.movies,dateList[day]);
function movie(){const a=films();mi=Math.min(mi,Math.max(0,a.length-1));const m=a[mi];$('#days').innerHTML=days.map((n,i)=>'<button data-day="'+i+'" aria-pressed="'+(i===day)+'">'+n+'</button>').join('');$('#movie').innerHTML=m?'<div class="filmTop">'+img(m.poster,'poster')+'<div><div class="eyebrow">'+esc(pretty(m.date))+'</div><h3 class="cardTitle">'+esc(m.title)+'</h3><div class="tag">'+esc([m.year,m.rating].filter(Boolean).join(' · '))+'</div><div class="ticket"><div class="showtimes" aria-label="Horarios">'+m.times.map(time=>'<strong>'+esc(time)+'</strong>').join('')+'</div><div class="roomLabel">'+esc(m.room)+'</div><b>'+(m.free?'ENTRADA LIBRE':money(m.price))+'</b></div></div></div><p class="synopsis">'+esc(m.synopsis)+'</p>'+(m.awards?'<p class="awards">'+esc(m.awards)+'</p>':'')+controls('cartelera',mi,a.length):empty('Sin funciones programadas para este día.');mt=Date.now()+(day?14000:35000)}
function stepMovie(d){let j=mi+d;if(j>=0&&j<films().length)mi=j;else{day=(day+d+3)%3;mi=d===1?0:Math.max(0,films().length-1)}movie()}
const products=()=>db.candy.filter(x=>x.active);
function candy(){const a=products();ci=(ci+a.length)%(a.length||1);const c=a[ci];$('#candy').innerHTML=c?img(c.poster,'product')+'<div class="eyebrow">'+esc(c.category)+'</div><h3 class="cardTitle">'+esc(c.title)+'</h3><div class="amount">'+money(c.price)+'</div><p class="description">'+esc(c.description)+'</p>'+controls('dulcería',ci,a.length):empty('Sin productos disponibles.');ct=Date.now()+8500}
function trailers(){const list=[...expandScreenings(db.movies).filter(m=>dateList.includes(m.date)).sort((a,b)=>a.date.localeCompare(b.date)).map(x=>({...x,label:'EN EXHIBICIÓN'})),...db.upcoming.filter(x=>x.active&&x.date>=dateList[0])];return list.filter((x,i)=>x.trailer&&list.findIndex(y=>y.trailer===x.trailer)===i)}
function fallback(msg){if(frame)frame.remove();frame=null;playing=false;$('#videoNote')&&($('#videoNote').textContent=msg);vt=Date.now()+14000}
function trailer(){const a=trailers();vi=(vi+a.length)%(a.length||1);const v=a[vi];frame=null;ready=false;playing=false;pendingEnded=false;$('#trailerDate').textContent=v?pretty(v.date).toUpperCase():'AVANCES';if(!v){$('#trailer').innerHTML=empty('Sin avances programados.');return}$('#trailer').innerHTML='<div class="video">'+img(v.poster,'')+'</div><p class="videoNote" id="videoNote"></p><div class="eyebrow">'+esc(v.label==='EN EXHIBICIÓN'?v.label:'PRÓXIMAMENTE'+(v.label==='PRÓXIMAMENTE'?'':' · '+v.label))+'</div><h3 class="cardTitle">'+esc(v.title)+'</h3><p class="description">'+pretty(v.date)+'</p>'+controls('trailers',vi,a.length);const y=yt(v.trailer);if(!y){fallback('Avance no disponible.');return}frame=document.createElement('iframe');frame.title='Trailer · '+v.title;frame.allow='autoplay; encrypted-media; fullscreen';frame.referrerPolicy='strict-origin-when-cross-origin';frame.src='https://www.youtube-nocookie.com/embed/'+y.id+'?enablejsapi=1&autoplay=1&mute=1&playsinline=1&start='+y.start+'&origin='+encodeURIComponent(location.origin);$('.video').append(frame);$('#videoNote').textContent='Preparando avance…';vt=Date.now()+12000}
function post(event,func,args=[]){frame?.contentWindow?.postMessage(JSON.stringify({event,func,args,id:'ccu'}),'https://www.youtube-nocookie.com')}
window.addEventListener('message',e=>{if(!frame||e.source!==frame.contentWindow||e.origin!=='https://www.youtube-nocookie.com')return;let m;try{m=JSON.parse(e.data)}catch{return}if(m.event==='onReady'){ready=true;for(const k of ['onStateChange','onError'])post('command','addEventListener',[k]);if(!paused)post('command','playVideo')}if(m.event==='onError')fallback('El proveedor no permite reproducir este avance.');if(m.event==='onStateChange'&&m.info===1){playing=true;frame.className='playing';$('#videoNote').textContent='';vt=Date.now()+240000}if(m.event==='onStateChange'&&m.info===0){if(paused)pendingEnded=true;else{vi++;trailer()}}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.day!==undefined){day=Number(b.dataset.day);mi=0;manual=Date.now()+45000;movie()}const d=Number(b.dataset.d);if(b.dataset.k==='cartelera'){stepMovie(d);manual=Date.now()+45000}if(b.dataset.k==='dulcería'){ci+=d;candy()}if(b.dataset.k==='trailers'){vi+=d;trailer()}});
$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'Reanudar rotación':'Pausar rotación';if(pendingEnded&&!paused){vi++;trailer()}else post('command',paused?'pauseVideo':'playVideo');mt=ct=vt=Date.now()+12000};
let last='';async function refresh(){try{const next=await (cloud?data():publishedData()),s=JSON.stringify(next)+dates()[0];if(last!==s){last=s;db=next;dateList=dates();movie();candy();trailer();renderPresentation(db.presentation)}$('#mode').textContent=cloud?'PROGRAMACIÓN EN LÍNEA':'CARTELERA EN LÍNEA · ACTUALIZACIÓN AUTOMÁTICA'}catch(e){$('#mode').textContent='Sin conexión · '+e.message}}
admin(refresh);await refresh();addEventListener('storage',refresh);setInterval(refresh,30000);
setInterval(()=>{const n=Date.now();$('#clock').textContent=new Intl.DateTimeFormat('es-MX',{timeZone:'America/Mexico_City',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(n);$('#today').textContent=pretty(dateList[0]);if(frame&&!ready)post('listening');if(paused||$('#panel').open)return;if(n>mt&&n>manual)stepMovie(1);if(n>ct){ci++;candy()}if(n>vt){if(frame&&!playing)fallback('Avance no disponible en esta pantalla.');else{vi++;trailer()}}},550)
